"use strict";(globalThis.webpackChunkmy_blog=globalThis.webpackChunkmy_blog||[]).push([[9724],{6048(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"tim-hieu-Java-platform","metadata":{"permalink":"/my-docusaurus/blog/tim-hieu-Java-platform","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2021-08-26-welcome/2026-11-02-tim-hieu-ve-Java.md","source":"@site/blog/2021-08-26-welcome/2026-11-02-tim-hieu-ve-Java.md","title":"T\xecm hi\u1ec3u Java Platform \u2013 Execution Flow & JVM Architecture","description":"1. Java Platform Overview \u2013 T\u1ed5ng quan n\u1ec1n t\u1ea3ng Java","date":"2026-11-02T00:00:00.000Z","tags":[{"inline":true,"label":"java","permalink":"/my-docusaurus/blog/tags/java"},{"inline":true,"label":"jvm","permalink":"/my-docusaurus/blog/tags/jvm"},{"inline":true,"label":"bytecode","permalink":"/my-docusaurus/blog/tags/bytecode"},{"inline":true,"label":"jdk","permalink":"/my-docusaurus/blog/tags/jdk"},{"inline":true,"label":"jre","permalink":"/my-docusaurus/blog/tags/jre"},{"inline":true,"label":"jit","permalink":"/my-docusaurus/blog/tags/jit"},{"inline":true,"label":"execution-flow","permalink":"/my-docusaurus/blog/tags/execution-flow"}],"readingTime":5.36,"hasTruncateMarker":false,"authors":[{"name":"Ph\u1ea1m Tr\u1ecdng Ngh\u0129a","title":"Qu\u1ea3n tr\u1ecb vi\xean","url":"https://github.com/trongnghia1811","imageURL":"https://github.com/trongnghia1811.png","key":"admin","page":null}],"frontMatter":{"slug":"tim-hieu-Java-platform","title":"T\xecm hi\u1ec3u Java Platform \u2013 Execution Flow & JVM Architecture","authors":["admin"],"tags":["java","jvm","bytecode","jdk","jre","jit","execution-flow"]},"unlisted":false,"nextItem":{"title":"CPython l\xe0 g\xec?","permalink":"/my-docusaurus/blog/bai-viet-thu-2"}},"content":"## 1. Java Platform Overview \u2013 T\u1ed5ng quan n\u1ec1n t\u1ea3ng Java\\r\\n\\r\\nNhi\u1ec1u ng\u01b0\u1eddi khi m\u1edbi ti\u1ebfp c\u1eadn th\u01b0\u1eddng ngh\u0129 Java \u0111\u01a1n thu\u1ea7n ch\u1ec9 l\xe0 m\u1ed9t **ng\xf4n ng\u1eef l\u1eadp tr\xecnh**. Tr\xean th\u1ef1c t\u1ebf, Java \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf nh\u01b0 m\u1ed9t **n\u1ec1n t\u1ea3ng ho\xe0n ch\u1ec9nh** (Java Platform), bao g\u1ed3m nhi\u1ec1u th\xe0nh ph\u1ea7n ph\u1ed1i h\u1ee3p ch\u1eb7t ch\u1ebd v\u1edbi nhau \u0111\u1ec3 ch\u01b0\u01a1ng tr\xecnh c\xf3 th\u1ec3 ch\u1ea1y \u1ed5n \u0111\u1ecbnh tr\xean nhi\u1ec1u h\u1ec7 \u0111i\u1ec1u h\xe0nh kh\xe1c nhau..\\r\\n\\r\\n\ud83d\udc49 Khi n\xf3i _\u201cl\u1eadp tr\xecnh Java\u201d_, th\u1ef1c ch\u1ea5t ta \u0111ang l\xe0m vi\u1ec7c v\u1edbi 3 tr\u1ee5 c\u1ed9t ch\xednh:\\r\\n\\r\\n- **Java Language** - c\xfa ph\xe1p v\xe0 quy t\u1eafc vi\u1ebft ch\u01b0\u01a1ng tr\xecnh\\r\\n- **JVM (Java Virtual Machine)** - m\xf4i tr\u01b0\u1eddng th\u1ef1c thi\\r\\n- **H\u1ec7 sinh th\xe1i th\u01b0 vi\u1ec7n & c\xf4ng c\u1ee5** - h\u1ed7 tr\u1ee3 ph\xe1t tri\u1ec3n v\xe0 ch\u1ea1y \u1ee9ng d\u1ee5ng\\r\\n\\r\\n### Tri\u1ebft l\xfd c\u1ed1t l\xf5i c\u1ee7a Java l\xe0:\\r\\n\\r\\n> **Write Once, Run Anywhere (WORA)**\\r\\n\\r\\n\u0110i\u1ec1u n\xe0y c\xf3 ngh\u0129a l\xe0:\\r\\n\\r\\nCode Java ch\u1ec9 c\u1ea7n vi\u1ebft m\u1ed9t l\u1ea7n\\r\\n\\r\\nC\xf3 th\u1ec3 ch\u1ea1y tr\xean Windows, Linux, macOS\u2026\\r\\n\\r\\nKh\xf4ng c\u1ea7n ch\u1ec9nh s\u1eeda m\xe3 ngu\u1ed3n cho t\u1eebng h\u1ec7 \u0111i\u1ec1u h\xe0nh\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Ph\xe2n bi\u1ec7t r\xf5 JDK \u2013 JRE \u2013 JVM (\u0111i\u1ec3m d\u1ec5 nh\u1ea7m nh\u1ea5t)\\r\\n\\r\\n\u0110\xe2y l\xe0 ph\u1ea7n **b\u1eaft bu\u1ed9c ph\u1ea3i hi\u1ec3u \u0111\xfang**, v\xec r\u1ea5t nhi\u1ec1u ng\u01b0\u1eddi h\u1ecdc Java l\xe2u n\u0103m v\u1eabn nh\u1ea7m l\u1eabn ba kh\xe1i ni\u1ec7m n\xe0y.\\r\\n\\r\\n### 2.1 JVM \u2013 Java Virtual Machine\\r\\n\\r\\n**JVM** l\xe0 m\u1ed9t **m\xe1y \u1ea3o**, kh\xf4ng t\u1ed3n t\u1ea1i v\u1eadt l\xfd, nh\u01b0ng \u0111\xf3ng vai tr\xf2 trung t\xe2m trong vi\u1ec7c ch\u1ea1y ch\u01b0\u01a1ng tr\xecnh Java.\\r\\n\\r\\n\u0110\u1eb7c \u0111i\u1ec3m quan tr\u1ecdng c\u1ee7a JVM:\\r\\n\\r\\n- Kh\xf4ng \u0111\u1ecdc \u0111\u01b0\u1ee3c file .java\\r\\n- Kh\xf4ng hi\u1ec3u file .exe\\r\\n- **Ch\u1ec9 th\u1ef1c thi file** .class **(bytecode)**\\r\\n\\r\\nNhi\u1ec7m v\u1ee5 ch\xednh c\u1ee7a JVM:\\r\\n\\r\\n- L\xe0m c\u1ea7u n\u1ed1i gi\u1eefa ch\u01b0\u01a1ng tr\xecnh Java v\xe0 h\u1ec7 \u0111i\u1ec1u h\xe0nh\\r\\n- Qu\u1ea3n l\xfd b\u1ed9 nh\u1edb\\r\\n- T\u1ed1i \u01b0u v\xe0 th\u1ef1c thi m\xe3 l\u1ec7nh\\r\\n\\r\\n\ud83d\udccc M\u1ed7i h\u1ec7 \u0111i\u1ec1u h\xe0nh c\xf3 **JVM ri\xeang** (Windows JVM, Linux JVM, macOS JVM),\\r\\nnh\u01b0ng **bytecode Java l\xe0 gi\u1ed1ng nhau** tr\xean m\u1ecdi n\u1ec1n t\u1ea3ng.\\r\\n\\r\\n---\\r\\n\\r\\n### 2.2 JRE \u2013 Java Runtime Environment\\r\\n\\r\\n**JRE** l\xe0 m\xf4i tr\u01b0\u1eddng d\xf9ng \u0111\u1ec3 ch\u1ea1y ch\u01b0\u01a1ng tr\xecnh Java.\\r\\n\\r\\nJRE bao g\u1ed3m:\\r\\n\\r\\n- JVM\\r\\n- Th\u01b0 vi\u1ec7n chu\u1ea9n c\u1ee7a Java (java.lang, java.util, java.io, \u2026)\\r\\n- C\xe1c th\xe0nh ph\u1ea7n c\u1ea5u h\xecnh runtime\\r\\n\\r\\n\ud83d\udc49 JRE **ch\u1ec9 d\xf9ng \u0111\u1ec3 ch\u1ea1y ch\u01b0\u01a1ng tr\xecnh**, kh\xf4ng ph\u1ee5c v\u1ee5 ph\xe1t tri\u1ec3n.\\r\\n\\r\\n\ud83d\udccc N\u1ebfu m\xe1y ch\u1ec9 c\xe0i JRE:\\r\\n\\r\\nCh\u1ea1y \u0111\u01b0\u1ee3c file .class\\r\\n\\r\\n\u274c Kh\xf4ng th\u1ec3 bi\xean d\u1ecbch file .java\\r\\n\\r\\n---\\r\\n\\r\\n### 2.3 JDK \u2013 Java Development Kit\\r\\n\\r\\n**JDK** l\xe0 b\u1ed9 c\xf4ng c\u1ee5 d\xe0nh cho **l\u1eadp tr\xecnh vi\xean Java**.\\r\\n\\r\\nJDK bao g\u1ed3m:\\r\\n\\r\\n- JRE\\r\\n- Tr\xecnh bi\xean d\u1ecbch javac\\r\\n- Tr\xecnh ch\u1ea1y java\\r\\n- C\xe1c c\xf4ng c\u1ee5 h\u1ed7 tr\u1ee3 kh\xe1c: javadoc, jdb, \u2026\\r\\n\\r\\n\ud83d\udc49 JDK cho ph\xe9p:\\r\\n\\r\\n- Vi\u1ebft code\\r\\n- Bi\xean d\u1ecbch\\r\\n- Ch\u1ea1y\\r\\n- Debug ch\u01b0\u01a1ng tr\xecnh\\r\\n\\r\\n\ud83d\udccc **Mu\u1ed1n h\u1ecdc ho\u1eb7c l\xe0m Java \u2192 lu\xf4n ph\u1ea3i c\xe0i JDK**\\r\\n\\r\\n---\\r\\n\\r\\n### 2.4 M\u1ed1i quan h\u1ec7 t\u1ed5ng th\u1ec3\\r\\n\\r\\nJDK <br />\\r\\n\u251c\u2500\u2500 JRE <br />\\r\\n\u2502 \u251c\u2500\u2500 JVM <br />\\r\\n\u2502 \u2514\u2500\u2500 Java Core Libraries <br />\\r\\n\u2514\u2500\u2500 Development Tools <br />\\r\\n\\r\\n---\\r\\n\\r\\n## 3. M\u1ed1i quan h\u1ec7 gi\u1eefa Java Language v\xe0 Java Platform\\r\\n\\r\\nHai kh\xe1i ni\u1ec7m n\xe0y **kh\xf4ng gi\u1ed1ng nhau**, nh\u01b0ng th\u01b0\u1eddng b\u1ecb d\xf9ng l\u1eabn.\\r\\n\\r\\n**Java Language**\\r\\n\\r\\n- C\xfa ph\xe1p\\r\\n- Ki\u1ec3u d\u1eef li\u1ec7u\\r\\n- L\u1eadp tr\xecnh h\u01b0\u1edbng \u0111\u1ed1i t\u01b0\u1ee3ng (class, object, inheritance, polymorphism)\\r\\n- File m\xe3 ngu\u1ed3n .java\\r\\n\\r\\n**Java Platform**\\r\\n\\r\\n- JVM\\r\\n- ClassLoader\\r\\n- Runtime Memory\\r\\n- Execution Engine\\r\\n- Garbage Collector\\r\\n\\r\\n\ud83d\udc49 **Java Language ch\u1ec9 l\xe0 ph\u1ea7n \u201cvi\u1ebft code\u201d**\\r\\n\ud83d\udc49 **Java Platform m\u1edbi quy\u1ebft \u0111\u1ecbnh ch\u01b0\u01a1ng tr\xecnh ch\u1ea1y nh\u01b0 th\u1ebf n\xe0o**\\r\\n\\r\\n---\\r\\n\\r\\n## 4. Java Execution Flow \u2013 Lu\u1ed3ng th\u1ef1c thi c\u1ee7a Java\\r\\n\\r\\nJVM **kh\xf4ng bao gi\u1edd ch\u1ea1y tr\u1ef1c ti\u1ebfp file** .java.\\r\\n\\r\\nQuy tr\xecnh th\u1ef1c thi ti\xeau chu\u1ea9n:\\r\\n\\r\\nIDE <br />\\r\\n\u2193 (Save) <br />\\r\\n`Hello.java` (\u1ed4 c\u1ee9ng) <br />\\r\\n\u2193 (Compile) <br />\\r\\n`javac Hello.java` <br />\\r\\n\u2193 <br />\\r\\n`Hello.class` (Bytecode) <br />\\r\\n\u2193 <br />\\r\\n\\r\\nJVM (RAM) <br />\\r\\n\u2193 <br />\\r\\nOS <br />\\r\\n\u2193 <br />\\r\\nCPU th\u1ef1c thi <br />\\r\\n\\r\\n\ud83d\udccc File .class m\u1edbi l\xe0 \u0111\u1ea7u v\xe0o th\u1ef1c s\u1ef1 c\u1ee7a JVM.\\r\\n\\r\\n---\\r\\n\\r\\n## 5. Compile-time v\xe0 Runtime trong Java\\r\\n\\r\\n### 5.1 Compile-time\\r\\n\\r\\n**X\u1ea3y ra khi ch\u1ea1y l\u1ec7nh:**\\r\\n\\r\\n```bash\\r\\njavac Hello.java\\r\\n```\\r\\n\\r\\nJava s\u1ebd:\\r\\n\\r\\n- Ki\u1ec3m tra c\xfa ph\xe1p\\r\\n- Ki\u1ec3m tra ki\u1ec3u d\u1eef li\u1ec7u\\r\\n- Bi\xean d\u1ecbch m\xe3 ngu\u1ed3n sang bytecode\\r\\n\\r\\nK\u1ebft qu\u1ea3:\\r\\n\\r\\n- T\u1ea1o ra file .class\\r\\n- **Ch\u01b0\u01a1ng tr\xecnh ch\u01b0a ch\u1ea1y**\\r\\n\\r\\n### 5.2 Runtime\\r\\n\\r\\nX\u1ea3y ra khi ch\u1ea1y:\\r\\n\\r\\n```bash\\r\\njava Hello\\r\\n```\\r\\n\\r\\n\u0110\u1ea7u v\xe0o:\\r\\n-File .class\\r\\n\\r\\nL\xfac n\xe0y JVM:\\r\\n\\r\\n- Load class\\r\\n- Verify bytecode\\r\\n- Th\u1ef1c thi ch\u01b0\u01a1ng tr\xecnh\\r\\n\\r\\n\ud83d\udccc Runtime m\u1edbi l\xe0 th\u1eddi \u0111i\u1ec3m ch\u01b0\u01a1ng tr\xecnh th\u1ef1c s\u1ef1 ho\u1ea1t \u0111\u1ed9ng.\\r\\n\\r\\n## 6. Bytecode l\xe0 g\xec? V\xec sao Java portable?\\r\\n\\r\\n**Bytecode** l\xe0 g\xec?\\r\\n\\r\\n- M\xe3 trung gian\\r\\n- Kh\xf4ng ph\u1ee5 thu\u1ed9c CPU hay h\u1ec7 \u0111i\u1ec1u h\xe0nh\\r\\n- \u0110\u01b0\u1ee3c thi\u1ebft k\u1ebf ri\xeang cho JVM\\r\\n\\r\\n\ud83d\udccc Bytecode:\\r\\n-Ch\u1ea1y tr\xean JVM\\r\\n-JVM d\u1ecbch ti\u1ebfp sang m\xe3 m\xe1y\\r\\n\\r\\nV\xec sao Java ch\u1ea1y \u0111a n\u1ec1n t\u1ea3ng?\\r\\n\\r\\nJava Source (.java)<br />\\r\\n\u2193<br />\\r\\nBytecode (.class)<br />\\r\\n\u2193<br />\\r\\n\u250c\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510 <br />\\r\\n\u2502 JVM Windows \u2502 \u2192 CPU Windows <br />\\r\\n\u2502 JVM Linux \u2502 \u2192 CPU Linux <br />\\r\\n\u2502 JVM macOS \u2502 \u2192 CPU macOS <br />\\r\\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\\r\\n\\r\\n\ud83d\udc49 Java kh\xf4ng ch\u1ea1y tr\u1ef1c ti\u1ebfp tr\xean OS\\r\\n\ud83d\udc49 JVM m\u1edbi l\xe0 th\u1ee9 giao ti\u1ebfp tr\u1ef1c ti\u1ebfp v\u1edbi h\u1ec7 \u0111i\u1ec1u h\xe0nh\\r\\n\\r\\n## 7. JVM Architecture \u2013 Ki\u1ebfn tr\xfac JVM\\r\\n\\r\\nJVM \u0111\u01b0\u1ee3c chia th\xe0nh 3 kh\u1ed1i ch\xednh:\\r\\n\\r\\n- ClassLoader Subsystem\\r\\n- Runtime Data Areas\\r\\n- Execution Engine\\r\\n\\r\\n## 8. ClassLoader Subsystem\\r\\n\\r\\nNhi\u1ec7m v\u1ee5:\\r\\n\\r\\n- Load .class v\xe0o JVM\\r\\n- Ki\u1ec3m tra t\xednh h\u1ee3p l\u1ec7\\r\\n- Chu\u1ea9n b\u1ecb class cho qu\xe1 tr\xecnh th\u1ef1c thi\\r\\n\\r\\n### C\xe1c lo\u1ea1i ClassLoader trong JVM\\r\\n\\r\\n- **Bootstrap ClassLoader**  \\r\\n  Load c\xe1c core class c\u1ee7a Java (v\xed d\u1ee5: `java.lang`, `java.util`)\\r\\n\\r\\n- **Platform ClassLoader** _(Java 9+)_  \\r\\n  Load c\xe1c th\u01b0 vi\u1ec7n thu\u1ed9c Java Platform (v\xed d\u1ee5: `java.sql`, `java.xml`)\\r\\n\\r\\n- **Application ClassLoader**  \\r\\n   Load c\xe1c class do l\u1eadp tr\xecnh vi\xean vi\u1ebft (classpath)\\r\\n  \ud83d\udccc Class ch\u1ec9 \u0111\u01b0\u1ee3c load khi c\u1ea7n thi\u1ebft\\r\\n\\r\\n## 9. Runtime Data Areas \u2013 V\xf9ng nh\u1edb trong JVM\\r\\n\\r\\n### 9.1 Method Area\\r\\n\\r\\nL\u01b0u:\\r\\n-Class metadata\\r\\n-Method info\\r\\n-Static variables\\r\\n\\r\\n### 9.2 Heap\\r\\n\\r\\n-L\u01b0u object\\r\\n-D\xf9ng chung cho to\xe0n JVM\\r\\n-Do Garbage Collector qu\u1ea3n l\xfd\\r\\n\\r\\n### 9.3 Stack\\r\\n\\r\\nM\u1ed7i thread c\xf3 stack ri\xeang\\r\\n\\r\\nL\u01b0u:\\r\\n-Local variables\\r\\n-Method call\\r\\n-Reference\\r\\n\\r\\n\ud83d\udccc Stack nh\u1ecf, nhanh\\r\\n\ud83d\udccc Heap l\u1edbn, ch\u1eadm h\u01a1n\\r\\n\\r\\n### 9.4 PC Register\\r\\n\\r\\nL\u01b0u \u0111\u1ecba ch\u1ec9 instruction \u0111ang ch\u1ea1y\\r\\n\\r\\n### 9.5 Native Method Stack\\r\\n\\r\\nD\xf9ng cho code native (C/C++)\\r\\n\\r\\n## 10. Execution Engine \u2013 B\u1ed9 m\xe1y th\u1ef1c thi\\r\\n\\r\\n### 10.1 Interpreter\\r\\n\\r\\n- \u0110\u1ecdc bytecode\\r\\n- Th\u1ef1c thi t\u1eebng instruction\\r\\n\\r\\n\ud83d\udccc \u01afu \u0111i\u1ec3m:\\r\\n\\r\\n- Ch\u1ea1y ngay\\r\\n\\r\\n\ud83d\udccc Nh\u01b0\u1ee3c \u0111i\u1ec3m:\\r\\n\\r\\n- Ch\u1eadm n\u1ebfu ch\u1ea1y l\u1eb7p nhi\u1ec1u l\u1ea7n\\r\\n\\r\\n### 10.2 JIT Compiler (Just-In-Time)\\r\\n\\r\\nJIT l\xe0m g\xec?\\r\\n\\r\\n- Ph\xe1t hi\u1ec7n \u0111o\u1ea1n code ch\u1ea1y nhi\u1ec1u\\r\\n- Bi\xean d\u1ecbch bytecode \u2192 m\xe3 m\xe1y\\r\\n- Cache l\u1ea1i \u0111\u1ec3 d\xf9ng sau\\r\\n\\r\\n\ud83d\udccc JVM hi\u1ec7n \u0111\u1ea1i:\\r\\n\\r\\n- Interpreter + JIT\\r\\n- T\u1ef1 t\u1ed1i \u01b0u khi ch\u01b0\u01a1ng tr\xecnh ch\u1ea1y\\r\\n\\r\\n## 11. T\u1ed5ng k\u1ebft\\r\\n\\r\\nTham kh\u1ea3o slide chi ti\u1ebft t\u1ea1i \u0111\xe2y :\\r\\n\\r\\n- \ud83d\udd17 https://www.canva.com/design/DAHApyPYZmw/AQAchpZL_3B77rpOe4-3YQ/edit\\r\\n\\r\\nJava kh\xf4ng \u0111\u01a1n thu\u1ea7n l\xe0 m\u1ed9t ng\xf4n ng\u1eef, m\xe0 l\xe0 m\u1ed9t n\u1ec1n t\u1ea3ng ho\xe0n ch\u1ec9nh g\u1ed3m JDK, JRE v\xe0 JVM. Ch\u01b0\u01a1ng tr\xecnh Java kh\xf4ng ch\u1ea1y tr\u1ef1c ti\u1ebfp tr\xean h\u1ec7 \u0111i\u1ec1u h\xe0nh m\xe0 ph\u1ea3i tr\u1ea3i qua qu\xe1 tr\xecnh bi\xean d\u1ecbch sang bytecode, sau \u0111\xf3 \u0111\u01b0\u1ee3c JVM th\xf4ng d\u1ecbch v\xe0 t\u1ed1i \u01b0u b\u1eb1ng JIT tr\u01b0\u1edbc khi CPU th\u1ef1c thi.\\r\\n\\r\\nVi\u1ec7c hi\u1ec3u r\xf5:\\r\\n\\r\\n-Java Platform <br/>\\r\\n-Execution Flow <br/>\\r\\n-JVM Architecture <br/>\\r\\n\\r\\ngi\xfap l\u1eadp tr\xecnh vi\xean:\\r\\n\\r\\n-Hi\u1ec3u s\xe2u b\u1ea3n ch\u1ea5t Java <br/>\\r\\n-Debug t\u1ed1t h\u01a1n <br/>\\r\\n-Vi\u1ebft code t\u1ed1i \u01b0u h\u01a1n <br/>\\r\\n-C\xf3 n\u1ec1n t\u1ea3ng h\u1ecdc Spring, JVM tuning, backend chuy\xean s\xe2u <br/>"},{"id":"bai-viet-thu-2","metadata":{"permalink":"/my-docusaurus/blog/bai-viet-thu-2","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/Cpython.md","source":"@site/blog/Cpython.md","title":"CPython l\xe0 g\xec?","description":"Trong b\xe0i vi\u1ebft n\xe0y, m\xecnh s\u1ebd chia s\u1ebb v\u1ec1 nh\u1eefng g\xec m\xecnh bi\u1ebft khi t\xecm hi\u1ec3u v\u1ec1 CPython.","date":"2026-02-02T11:20:01.000Z","tags":[{"inline":false,"label":"Docusaurus","permalink":"/my-docusaurus/blog/tags/docusaurus","description":"Docusaurus tag description"},{"inline":true,"label":"blog","permalink":"/my-docusaurus/blog/tags/blog"},{"inline":true,"label":"huong-dan","permalink":"/my-docusaurus/blog/tags/huong-dan"},{"inline":true,"label":"lap-trinh","permalink":"/my-docusaurus/blog/tags/lap-trinh"}],"readingTime":4.53,"hasTruncateMarker":false,"authors":[{"name":"Ph\u1ea1m Tr\u1ecdng Ngh\u0129a","title":"Qu\u1ea3n tr\u1ecb vi\xean","url":"https://github.com/trongnghia1811","imageURL":"https://github.com/trongnghia1811.png","key":"admin","page":null}],"frontMatter":{"slug":"bai-viet-thu-2","title":"CPython l\xe0 g\xec?","authors":["admin"],"tags":["docusaurus","blog","huong-dan","lap-trinh"]},"unlisted":false,"prevItem":{"title":"T\xecm hi\u1ec3u Java Platform \u2013 Execution Flow & JVM Architecture","permalink":"/my-docusaurus/blog/tim-hieu-Java-platform"},"nextItem":{"title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","permalink":"/my-docusaurus/blog/bai-viet-dau-tien"}},"content":"Trong b\xe0i vi\u1ebft n\xe0y, m\xecnh s\u1ebd chia s\u1ebb v\u1ec1 nh\u1eefng g\xec m\xecnh bi\u1ebft khi t\xecm hi\u1ec3u v\u1ec1 CPython.\\r\\n\\r\\n- CPython l\xe0 g\xec?\\r\\n- H\xe0nh tr\xecnh t\u1eeb d\xf2ng code xu\u1ed1ng IDE di\u1ec5n ra th\u1ebf n\xe0o?\\r\\n- C\xe1ch CPython qu\u1ea3n l\xfd b\u1ed9 nh\u1edb?\\r\\n\\r\\n## 1. CPython l\xe0 g\xec?\\r\\n\\r\\nTr\u01b0\u1edbc khi \u0111i v\xe0o chi ti\u1ebft, ch\xfang ta c\u1ea7n l\xe0m r\xf5: Python l\xe0 ng\xf4n ng\u1eef (t\u1eadp h\u1ee3p c\xe1c quy t\u1eafc ng\u1eef ph\xe1p). C\xf2n CPython l\xe0 ph\u1ea7n m\u1ec1m th\u1ef1c thi c\xe1c quy t\u1eafc \u0111\xf3 (Implementation).\\r\\n\\r\\nKhi ta t\u1ea3i Python t\u1eeb trang ch\u1ee7 v\u1ec1 t\u1ee9c l\xe0 ta \u0111ang t\u1ea3i CPython. N\xf3 \u0111\u01b0\u1ee3c vi\u1ebft ho\xe0n to\xe0n b\u1eb1ng C. N\xf3 v\u1eeba l\xe0 Compiler (bi\xean d\u1ecbch), v\u1eeba l\xe0 Interpreter (th\xf4ng d\u1ecbch).\\r\\n\\r\\n## 2. H\xe0nh tr\xecnh c\u1ee7a Code: Pipeline t\u1eeb A \u0111\u1ebfn Z\\r\\n\\r\\nCho v\xed d\u1ee5 sau:\\r\\n\\r\\n```\\r\\na = 10\\r\\nprint(a + 5)\\r\\n```\\r\\n\\r\\n\u0110\u1ec3 m\xe1y t\xednh hi\u1ec3u \u0111\u01b0\u1ee3c, d\xf2ng code n\xe0y ph\u1ea3i tr\u1ea3i qua m\u1ed9t qu\xe1 tr\xecnh nghi\xeam ng\u1eb7t g\u1ed3m 4 giai \u0111o\u1ea1n:\\r\\n\\r\\n### Giai \u0111o\u1ea1n 1: Lexing (Ph\xe2n t\xedch t\u1eeb v\u1ef1ng)\\r\\n\\r\\nCPython \u0111\u1ecdc file code c\u1ee7a ta nh\u01b0 m\u1ed9t chu\u1ed7i v\u0103n b\u1ea3n v\xf4 ngh\u0129a. Lexer s\u1ebd b\u0103m nh\u1ecf chu\u1ed7i \u0111\xf3 th\xe0nh c\xe1c \u0111\u01a1n v\u1ecb c\xf3 ngh\u0129a g\u1ecdi l\xe0 Tokens.\\r\\n\\r\\n```\\r\\na -> NAME\\r\\n= -> OP\\r\\n10 -> NUMBER\\r\\n```\\r\\n\\r\\nLexer c\u1ee7a Python r\u1ea5t \u0111\u1eb7c bi\u1ec7t: n\xf3 quan t\xe2m \u0111\u1ebfn c\u1ea3 kho\u1ea3ng tr\u1eafng (indentation) \u0111\u1ec3 sinh ra c\xe1c token INDENT v\xe0 DEDENT, gi\xfap \u0111\u1ecbnh h\xecnh kh\u1ed1i l\u1ec7nh.\\r\\n\\r\\n### Giai \u0111o\u1ea1n 2: Parsing & AST (X\xe2y d\u1ef1ng c\xe2y c\xfa ph\xe1p tr\u1eebu t\u01b0\u1ee3ng)\\r\\n\\r\\nT\u1eeb nh\u1eefng token r\u1eddi r\u1ea1c tr\xean, Parser s\u1ebd s\u1eafp x\u1ebfp ch\xfang l\u1ea1i theo ng\u1eef ph\xe1p v\xe0 d\u1ef1ng l\xean m\u1ed9t C\xe2y C\xfa ph\xe1p Tr\u1eebu t\u01b0\u1ee3ng (Abstract Syntax Tree - AST). M\xe1y t\xednh kh\xf4ng \u0111\u1ecdc t\u1eeb tr\xe1i sang ph\u1ea3i nh\u01b0 ng\u01b0\u1eddi, n\xf3 nh\xecn c\u1ea5u tr\xfac c\xe2y \u0111\u1ec3 bi\u1ebft c\xe1i n\xe0o l\xe0 cha, c\xe1i n\xe0o l\xe0 con, c\xe1i n\xe0o \u01b0u ti\xean th\u1ef1c hi\u1ec7n tr\u01b0\u1edbc (v\xed d\u1ee5: nh\xe2n chia tr\u01b0\u1edbc, c\u1ed9ng tr\u1eeb sau).\\r\\n\\r\\n### Giai \u0111o\u1ea1n 3: Compilation (Bi\xean d\u1ecbch sang Bytecode)\\r\\n\\r\\n\u0110\u1ebfn \u0111\xe2y, m\u1ed9t b\u01b0\u1edbc c\u1ef1c k\u1ef3 quan tr\u1ecdng di\u1ec5n ra: CPython b\u1eaft bu\u1ed9c ph\u1ea3i d\u1ecbch AST sang m\u1ed9t ng\xf4n ng\u1eef trung gian g\u1ecdi l\xe0 Bytecode (.pyc).\\r\\n\\r\\n- **L\u01b0u \xfd**: Python kh\xf4ng ch\u1ea1y tr\u1ef1c ti\u1ebfp source code (.py) t\u1eebng d\xf2ng m\u1ed9t nh\u01b0 nhi\u1ec1u ng\u01b0\u1eddi l\u1ea7m t\u01b0\u1edfng.\\r\\n\\r\\n- N\xf3 lu\xf4n ph\u1ea3i Compile sang Bytecode tr\u01b0\u1edbc. Bytecode n\xe0y kh\xf4ng ph\u1ea3i l\xe0 M\xe3 m\xe1y (Machine Code) \u0111\u1ec3 CPU ch\u1ea1y, m\xe0 l\xe0 t\u1eadp l\u1ec7nh d\xe0nh ri\xeang cho m\xe1y \u1ea3o Python.\\r\\n\\r\\n### Giai \u0111o\u1ea1n 4: Python Virtual Machine (PVM)\\r\\n\\r\\n\u0110\xe2y l\xe0 n\u01a1i ch\u01b0\u01a1ng tr\xecnh th\u1ef1c s\u1ef1 ch\u1ea1y. PVM l\xe0 m\u1ed9t v\xf2ng l\u1eb7p v\xf4 t\u1eadn, ho\u1ea1t \u0111\u1ed9ng nh\u01b0 m\u1ed9t \\"CPU \u1ea3o\\".\\r\\nV\u1edbi l\u1ec7nh a = 10, m\xf4 h\xecnh b\u1ed9 nh\u1edb ho\u1ea1t \u0111\u1ed9ng kh\xe1c h\u1eb3n v\u1edbi C/Java truy\u1ec1n th\u1ed1ng:\\r\\n\\r\\n- Heap Memory (Ch\u1ee9a Object): PVM t\u1ea1o m\u1ed9t object int c\xf3 gi\xe1 tr\u1ecb l\xe0 10 n\u1eb1m tr\xean Heap.\\r\\n\\r\\n- Stack Memory (Ch\u1ee9a Reference): PVM \u0111\u1ea9y c\xe1i t\xean bi\u1ebfn a (reference) v\xe0o Stack frame hi\u1ec7n t\u1ea1i v\xe0 tr\u1ecf n\xf3 t\u1edbi \u0111\u1ecba ch\u1ec9 c\u1ee7a object 10 b\xean Heap.\\r\\n\\r\\n**Kh\xe1c bi\u1ec7t m\u1ea5u ch\u1ed1t**: Stack trong Python kh\xf4ng ch\u1ee9a \\"gi\xe1 tr\u1ecb\\" (value), n\xf3 ch\u1ec9 ch\u1ee9a c\xe1c tham chi\u1ebfu. M\u1ecdi th\u1ee9 trong Python (s\u1ed1, chu\u1ed7i, boolean...) \u0111\u1ec1u l\xe0 Object v\xe0 n\u1eb1m tr\xean Heap.\\r\\nSau c\xf9ng, PVM \u0111\u1ecdc t\u1eebng d\xf2ng Bytecode, g\u1ecdi c\xe1c h\xe0m C t\u01b0\u01a1ng \u1ee9ng \u0111\u1ec3 CPU th\u1ef1c thi.\\r\\n\\r\\n## 3. C\xe1ch CPython qu\u1ea3n l\xfd b\u1ed9 nh\u1edb?\\r\\n\\r\\nCPython qu\u1ea3n l\xed b\u1ed9 nh\u1edb c\u1ef1c k\xec tinh vi\\r\\n\\r\\n### M\u1ecdi th\u1ee9 \u0111\u1ec1u l\xe0 Object (PyObject)\\r\\n\\r\\nTrong CPython, s\u1ed1 10 kh\xf4ng ch\u1ec9 l\xe0 4 bytes nh\u1ecb ph\xe2n. N\xf3 l\xe0 m\u1ed9t struct (c\u1ea5u tr\xfac) trong C t\xean l\xe0 PyObject. N\xf3 ch\u1ee9a r\u1ea5t nhi\u1ec1u metadata:\\r\\n\\r\\n- N\xf3 thu\u1ed9c ki\u1ec3u g\xec (int, str)?\\r\\n- C\xf3 bao nhi\xeau ng\u01b0\u1eddi \u0111ang d\xf9ng n\xf3 (Reference Count)?\\r\\n\\r\\n### Pymalloc & C\u01a1 ch\u1ebf c\u1ea5p ph\xe1t\\r\\n\\r\\nCPython kh\xf4ng g\u1ecdi malloc (xin RAM t\u1eeb OS) m\u1ed7i khi ta t\u1ea1o m\u1ed9t bi\u1ebfn, v\xec vi\u1ec7c \u0111\xf3 r\u1ea5t ch\u1eadm. Thay v\xe0o \u0111\xf3, n\xf3 d\xf9ng Pymalloc:\\r\\n\\r\\n- N\xf3 xin s\u1eb5n nh\u1eefng v\xf9ng \u0111\u1ea5t l\u1edbn (Arenas).\\r\\n- Chia nh\u1ecf th\xe0nh c\xe1c h\u1ed3 (Pools).\\r\\n- Khi ta c\u1ea7n, n\xf3 \\"ph\xe1t\\" ngay m\u1ed9t m\u1ea3nh nh\u1ecf. \u0110\xe2y l\xe0 l\xfd do t\u1ea1o object nh\u1ecf trong Python r\u1ea5t nhanh.\\r\\n\\r\\n### D\u1ecdn r\xe1c (Garbage Collection)\\r\\n\\r\\nL\xe0m sao Python bi\u1ebft khi n\xe0o x\xf3a bi\u1ebfn \u0111\u1ec3 gi\u1ea3i ph\xf3ng RAM?\\r\\n\\r\\n1. **Reference Counting (Ch\u1ee7 \u0111\u1ea1o)**: M\u1ed7i object c\xf3 m\u1ed9t b\u1ed9 \u0111\u1ebfm. C\u1ee9 ai d\xf9ng bi\u1ebfn th\xec \u0111\u1ebfm +1, kh\xf4ng d\xf9ng n\u1eefa (ho\u1eb7c d\xf9ng del) th\xec -1. Khi b\u1ed9 \u0111\u1ebfm v\u1ec1 0, object b\u1ecb x\xf3a ngay l\u1eadp t\u1ee9c.\\r\\n\\r\\n2. **Generational Garbage Collection (X\u1eed l\xfd Cyclic Reference):**\\r\\n\\r\\n- V\u1ea5n \u0111\u1ec1: N\u1ebfu A tr\u1ecf t\u1edbi B, v\xe0 B tr\u1ecf ng\u01b0\u1ee3c l\u1ea1i A (V\xf2ng tham chi\u1ebfu), th\xec Reference Count c\u1ee7a c\u1ea3 hai kh\xf4ng bao gi\u1edd v\u1ec1 0, d\xf9 ta kh\xf4ng d\xf9ng ch\xfang n\u1eefa. \u0110\xe2y l\xe0 r\xf2 r\u1ec9 b\u1ed9 nh\u1edb.\\r\\n\\r\\n- Gi\u1ea3i ph\xe1p: CPython s\u1eed d\u1ee5ng m\u1ed9t b\u1ed9 gom r\xe1c th\u1ebf h\u1ec7 (Generational GC). N\xf3 \u0111\u1ecbnh k\u1ef3 qu\xe9t c\xe1c object d\u1ea1ng \\"container\\" (list, dict, class...) \u0111\u1ec3 ph\xe1t hi\u1ec7n c\xe1c v\xf2ng tr\xf2n kh\xe9p k\xedn n\xe0y v\xe0 d\u1ecdn d\u1eb9p ch\xfang.\\r\\n\\r\\n---\\r\\n\\r\\n##\\r\\n\\r\\nC\xe1c b\u1ea1n c\xf3 th\u1ec3 tham kh\u1ea3o qua slide d\u01b0\u1edbi \u0111\xe2y \u0111\u1ec3 hi\u1ec3u s\xe2u h\u01a1n v\u1ec1 CPython:\\r\\n\\r\\n- \ud83d\udd17 https://www.canva.com/design/DAG_3EC7Suw/1LjWwYMgO59FCa64VBrI3w/edit\\r\\n  (Slide s\u1ebd m\u1edf \u1edf tab m\u1edbi \u0111\u1ec3 xem \u0111\u1ea7y \u0111\u1ee7 v\xe0 r\xf5 r\xe0ng h\u01a1n)\\r\\n\\r\\n---\\r\\n\\r\\n## 4. K\u1ebft lu\u1eadn\\r\\n\\r\\nH\xe0nh tr\xecnh t\u1eeb d\xf2ng code tr\xean IDE \u0111\u1ebfn khi OS th\u1ef1c thi l\xe0 m\u1ed9t ch\u1eb7ng \u0111\u01b0\u1eddng d\xe0i \u0111i qua Lexer, Parser, Compiler v\xe0 PVM. CPython kh\xf4ng ch\u1ec9 l\xe0 m\u1ed9t tr\xecnh th\xf4ng d\u1ecbch, n\xf3 l\xe0 m\u1ed9t ki\u1ec7t t\xe1c k\u1ef9 thu\u1eadt k\u1ebft h\u1ee3p gi\u1eefa s\u1ef1 linh ho\u1ea1t c\u1ee7a ng\xf4n ng\u1eef b\u1eadc cao v\xe0 s\u1ef1 ch\u1eb7t ch\u1ebd c\u1ee7a C.\\r\\n\\r\\nHy v\u1ecdng b\xe0i vi\u1ebft n\xe0y gi\xfap b\u1ea1n c\xf3 c\xe1i nh\xecn s\xe2u s\u1eafc h\u01a1n v\u1ec1 c\xf4ng c\u1ee5 m\xecnh \u0111ang d\xf9ng h\xe0ng ng\xe0y. \u0110\u1eebng ch\u1ec9 code, h\xe3y hi\u1ec3u code ch\u1ea1y nh\u01b0 th\u1ebf n\xe0o!"},{"id":"bai-viet-dau-tien","metadata":{"permalink":"/my-docusaurus/blog/bai-viet-dau-tien","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/baivietdautien.md","source":"@site/blog/baivietdautien.md","title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","description":"Trong b\xe0i vi\u1ebft n\xe0y, m\xecnh s\u1ebd h\u01b0\u1edbng d\u1eabn chi ti\u1ebft c\xe1ch t\u1ea1o m\u1ed9t blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus \u2013 m\u1ed9t c\xf4ng c\u1ee5 r\u1ea5t m\u1ea1nh \u0111\u1ec3 x\xe2y d\u1ef1ng website t\xe0i li\u1ec7u v\xe0 blog t\u0129nh.","date":"2026-01-22T16:33:26.000Z","tags":[{"inline":false,"label":"Docusaurus","permalink":"/my-docusaurus/blog/tags/docusaurus","description":"Docusaurus tag description"},{"inline":true,"label":"blog","permalink":"/my-docusaurus/blog/tags/blog"},{"inline":true,"label":"huong-dan","permalink":"/my-docusaurus/blog/tags/huong-dan"},{"inline":true,"label":"lap-trinh","permalink":"/my-docusaurus/blog/tags/lap-trinh"}],"readingTime":1.02,"hasTruncateMarker":false,"authors":[{"name":"Ph\u1ea1m Tr\u1ecdng Ngh\u0129a","title":"Qu\u1ea3n tr\u1ecb vi\xean","url":"https://github.com/trongnghia1811","imageURL":"https://github.com/trongnghia1811.png","key":"admin","page":null}],"frontMatter":{"slug":"bai-viet-dau-tien","title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","authors":["admin"],"tags":["docusaurus","blog","huong-dan","lap-trinh"]},"unlisted":false,"prevItem":{"title":"CPython l\xe0 g\xec?","permalink":"/my-docusaurus/blog/bai-viet-thu-2"},"nextItem":{"title":"Welcome","permalink":"/my-docusaurus/blog/welcome"}},"content":"Trong b\xe0i vi\u1ebft n\xe0y, m\xecnh s\u1ebd h\u01b0\u1edbng d\u1eabn chi ti\u1ebft c\xe1ch t\u1ea1o m\u1ed9t blog c\xe1 nh\xe2n b\u1eb1ng _Docusaurus_ \u2013 m\u1ed9t c\xf4ng c\u1ee5 r\u1ea5t m\u1ea1nh \u0111\u1ec3 x\xe2y d\u1ef1ng website t\xe0i li\u1ec7u v\xe0 blog t\u0129nh.\\r\\n\\r\\nB\xe0i vi\u1ebft ph\xf9 h\u1ee3p cho:\\r\\n\\r\\n- Sinh vi\xean IT\\r\\n- Ng\u01b0\u1eddi m\u1edbi h\u1ecdc web\\r\\n- Ng\u01b0\u1eddi mu\u1ed1n c\xf3 blog c\xe1 nh\xe2n chuy\xean nghi\u1ec7p\\r\\n\\r\\n---\\r\\n\\r\\n## 1. Docusaurus l\xe0 g\xec?\\r\\n\\r\\nDocusaurus l\xe0 m\u1ed9t framework m\xe3 ngu\u1ed3n m\u1edf do Facebook ph\xe1t tri\u1ec3n, d\xf9ng \u0111\u1ec3 t\u1ea1o:\\r\\n\\r\\n- Blog c\xe1 nh\xe2n\\r\\n- Website t\xe0i li\u1ec7u\\r\\n- Website gi\u1edbi thi\u1ec7u d\u1ef1 \xe1n\\r\\n\\r\\n\u01afu \u0111i\u1ec3m:\\r\\n\\r\\n- Mi\u1ec5n ph\xed\\r\\n- D\u1ec5 d\xf9ng\\r\\n- Vi\u1ebft b\xe0i b\u1eb1ng Markdown\\r\\n- Deploy d\u1ec5 l\xean GitHub Pages\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Chu\u1ea9n b\u1ecb m\xf4i tr\u01b0\u1eddng\\r\\n\\r\\nB\u1ea1n c\u1ea7n c\xe0i s\u1eb5n:\\r\\n\\r\\n- Node.js (phi\xean b\u1ea3n >= 18)\\r\\n- npm (\u0111i k\xe8m Node.js)\\r\\n\\r\\nKi\u1ec3m tra b\u1eb1ng l\u1ec7nh:\\r\\n\\r\\nnode -v\\r\\nnpm -v\\r\\n\\r\\n---\\r\\n\\r\\n##\\r\\n\\r\\nSlide d\u01b0\u1edbi \u0111\xe2y m\xf4 t\u1ea3 to\xe0n b\u1ed9 quy tr\xecnh x\xe2y d\u1ef1ng website,\\r\\nt\u1eeb b\u01b0\u1edbc kh\u1edfi t\u1ea1o project cho \u0111\u1ebfn khi deploy (tri\u1ec3n khai) website l\xean GitHub Pages.\\r\\n\\r\\nXem slide h\u01b0\u1edbng d\u1eabn chi ti\u1ebft t\u1ea1i \u0111\xe2y:\\r\\n\\r\\n- \ud83d\udd17 https://www.canva.com/design/DAG-x-HN2J0/AXmxIe_VDDip6aalEPP8PQ/view\\r\\n\\r\\n(Slide s\u1ebd m\u1edf \u1edf tab m\u1edbi \u0111\u1ec3 xem \u0111\u1ea7y \u0111\u1ee7 v\xe0 r\xf5 r\xe0ng h\u01a1n)\\r\\n\\r\\n---\\r\\n\\r\\n## 4. K\u1ebft lu\u1eadn\\r\\n\\r\\nSau khi xem slide, ng\u01b0\u1eddi m\u1edbi c\xf3 th\u1ec3:\\r\\n\\r\\n- T\u1ea1o project Docusaurus\\r\\n- Vi\u1ebft b\xe0i blog\\r\\n- \u0110\u1ea9y source code l\xean GitHub\\r\\n- Deploy website b\u1eb1ng GitHub Pages\\r\\n\\r\\n---"},{"id":"welcome","metadata":{"permalink":"/my-docusaurus/blog/welcome","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2021-08-26-welcome/index.md","source":"@site/blog/2021-08-26-welcome/index.md","title":"Welcome","description":"Docusaurus blogging features are powered by the blog plugin.","date":"2021-08-26T00:00:00.000Z","tags":[{"inline":false,"label":"Facebook","permalink":"/my-docusaurus/blog/tags/facebook","description":"Facebook tag description"},{"inline":false,"label":"Hello","permalink":"/my-docusaurus/blog/tags/hello","description":"Hello tag description"},{"inline":false,"label":"Docusaurus","permalink":"/my-docusaurus/blog/tags/docusaurus","description":"Docusaurus tag description"}],"readingTime":0.56,"hasTruncateMarker":true,"authors":[{"name":"S\xe9bastien Lorber","title":"Docusaurus maintainer","url":"https://sebastienlorber.com","page":{"permalink":"/my-docusaurus/blog/authors/all-sebastien-lorber-articles"},"socials":{"x":"https://x.com/sebastienlorber","linkedin":"https://www.linkedin.com/in/sebastienlorber/","github":"https://github.com/slorber","newsletter":"https://thisweekinreact.com"},"imageURL":"https://github.com/slorber.png","key":"slorber"},{"name":"Yangshun Tay","title":"Ex-Meta Staff Engineer, Co-founder GreatFrontEnd","url":"https://linkedin.com/in/yangshun","page":{"permalink":"/my-docusaurus/blog/authors/yangshun"},"socials":{"x":"https://x.com/yangshunz","linkedin":"https://www.linkedin.com/in/yangshun/","github":"https://github.com/yangshun","newsletter":"https://www.greatfrontend.com"},"imageURL":"https://github.com/yangshun.png","key":"yangshun"}],"frontMatter":{"slug":"welcome","title":"Welcome","authors":["slorber","yangshun"],"tags":["facebook","hello","docusaurus"]},"unlisted":false,"prevItem":{"title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","permalink":"/my-docusaurus/blog/bai-viet-dau-tien"}},"content":"[Docusaurus blogging features](https://docusaurus.io/docs/blog) are powered by the [blog plugin](https://docusaurus.io/docs/api/plugins/@docusaurus/plugin-content-blog).\\n\\nHere are a few tips you might find useful.\\n\\n\x3c!-- truncate --\x3e\\n\\nSimply add Markdown files (or folders) to the `blog` directory.\\n\\nRegular blog authors can be added to `authors.yml`.\\n\\nThe blog post date can be extracted from filenames, such as:\\n\\n- `2019-05-30-welcome.md`\\n- `2019-05-30-welcome/index.md`\\n\\nA blog post folder can be convenient to co-locate blog post images:\\n\\n![Docusaurus Plushie](./docusaurus-plushie-banner.jpeg)\\n\\nThe blog supports tags as well!\\n\\n**And if you don\'t want a blog**: just delete this directory, and use `blog: false` in your Docusaurus config."}]}}')}}]);